-- ---------------------------------------------------------------------------
-- Hand-written from here down.
-- ---------------------------------------------------------------------------

-- 1. The value lists are closed. Each one is the list in domains/cases.ts or in
--    shared/events.ts (SEVERITIES, SENSITIVITY_CLASSES), and a new value is a
--    migration, because the domain and these lists must change together.
ALTER TABLE "cases"
  ADD CONSTRAINT "cases_kind_known"
  CHECK ("kind" IN ('customer', 'learner', 'complaint'));

ALTER TABLE "cases"
  ADD CONSTRAINT "cases_state_known"
  CHECK ("state" IN ('open', 'acknowledged', 'resolved', 'closed', 'withdrawn'));

ALTER TABLE "cases"
  ADD CONSTRAINT "cases_visibility_tier_known"
  CHECK ("visibilityTier" IN ('public', 'internal', 'restricted', 'confidential', 'regulated'));

ALTER TABLE "cases"
  ADD CONSTRAINT "cases_severity_known"
  CHECK ("severity" IN ('S0_INFO', 'S1_ATTENTION', 'S2_WARNING', 'S3_HIGH_RISK', 'S4_CRITICAL'));

ALTER TABLE "case_events"
  ADD CONSTRAINT "case_events_to_state_known"
  CHECK ("toState" IN ('open', 'acknowledged', 'resolved', 'closed', 'withdrawn'));

ALTER TABLE "case_events"
  ADD CONSTRAINT "case_events_from_state_known"
  CHECK ("fromState" IS NULL OR "fromState" IN ('open', 'acknowledged', 'resolved', 'closed', 'withdrawn'));

-- 2. The backup is never the owner. The domain refuses it with a 422 first; this
--    is the floor for a writer that goes around the domain.
ALTER TABLE "cases"
  ADD CONSTRAINT "cases_backup_not_owner"
  CHECK ("backupPartyId" IS NULL OR "backupPartyId" <> "ownerPartyId");

-- 3. Silence never acknowledges. An acknowledgement records who and when, and the
--    two are set together by the human act that moves a case to acknowledged. A
--    case that is acknowledged, resolved or closed carries both. A case the
--    overdue job flagged still reads open, with neither.
ALTER TABLE "cases"
  ADD CONSTRAINT "cases_acknowledgement_recorded"
  CHECK (("acknowledgedById" IS NULL) = ("acknowledgedAt" IS NULL));

ALTER TABLE "cases"
  ADD CONSTRAINT "cases_acknowledged_states_have_acknowledger"
  CHECK ("state" NOT IN ('acknowledged', 'resolved', 'closed') OR "acknowledgedAt" IS NOT NULL);

-- 4. A subject is named both ways or neither. A half-named subject points at nothing.
ALTER TABLE "cases"
  ADD CONSTRAINT "cases_subject_pair"
  CHECK (("subjectType" IS NULL) = ("subjectId" IS NULL));

-- 5. A remedy is paise and is never negative. A remedy is an amount the company
--    pays out; a negative one would be a receivable recorded as a remedy.
ALTER TABLE "cases"
  ADD CONSTRAINT "cases_remedy_non_negative"
  CHECK ("remedyAmountMinor" IS NULL OR "remedyAmountMinor" >= 0);

-- 6. The history is append-only. No application path updates or deletes a row
--    (the domain writes one per change), so the trigger refuses both for every
--    role, the table owner included. A correction is a new row.
CREATE OR REPLACE FUNCTION "case_events_immutable"()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'case events are immutable; a correction is a new event'
    USING ERRCODE = 'check_violation';
END
$$;

CREATE TRIGGER "case_events_immutable"
  BEFORE UPDATE OR DELETE ON "case_events"
  FOR EACH ROW EXECUTE FUNCTION "case_events_immutable"();

-- 7. Row-level security on the new tables. Written out, not looped, as in
--    20261013100000_commitment_record, so rlsMigrationOrder.test.ts can read it.
ALTER TABLE "cases" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "cases" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "tenant_isolation" ON "cases";
CREATE POLICY "tenant_isolation" ON "cases"
  USING ("tenantId" = current_setting('app.tenant_id', true))
  WITH CHECK ("tenantId" = current_setting('app.tenant_id', true));

ALTER TABLE "case_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "case_events" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "tenant_isolation" ON "case_events";
CREATE POLICY "tenant_isolation" ON "case_events"
  USING ("tenantId" = current_setting('app.tenant_id', true))
  WITH CHECK ("tenantId" = current_setting('app.tenant_id', true));

ALTER TABLE "case_exception_links" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "case_exception_links" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "tenant_isolation" ON "case_exception_links";
CREATE POLICY "tenant_isolation" ON "case_exception_links"
  USING ("tenantId" = current_setting('app.tenant_id', true))
  WITH CHECK ("tenantId" = current_setting('app.tenant_id', true));

-- 8. The application role may use the new tables. Guarded, as in the commitment
--    migration: on a fresh database the role is created by tenant_rls, which
--    grants on every table anyway.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'kaizen_app') THEN
    GRANT SELECT, INSERT, UPDATE, DELETE ON "cases" TO "kaizen_app";
    GRANT SELECT, INSERT ON "case_events" TO "kaizen_app";
    GRANT SELECT, INSERT ON "case_exception_links" TO "kaizen_app";
  END IF;
END
$$;
